mapper.select:
SELECT *
FROM ai_chat_message
WHERE user_id = #{userId}
  AND session_id = #{sessionId}
ORDER BY create_time

mapper.delete:
DELETE FROM ai_chat_message
WHERE user_id = #{userId}
  AND session_id = #{sessionId}

mapper.select:
SELECT COUNT(*)
FROM ai_chat_message
WHERE user_id = #{userId}
  AND id = #{messageId}
  AND role = 'assistant'
